INSTALL httpfs;

LOAD httpfs;
SET s3_region='us-west-2';
SET VARIABLE overture_release = '2026-10-21.0';
SET VARIABLE overture_s3_base = 's3://overturemaps-us-west-2';

-- Direct public S3 recipe. The future open_data_duck extension should wrap
-- this release/path logic instead of relying on a separate Overture plugin.
SELECT *
FROM read_parquet(
  getvariable('overture_s3_base') || '/release/' || getvariable('overture_release') || '/theme=places/type=place/*',
  hive_partitioning = true
)
WHERE bbox.xmin <= -149
  AND bbox.xmax >= -150
  AND bbox.ymin <= 61
  AND bbox.ymax >= 60
LIMIT 10;

INSTALL spatial;

LOAD spatial;

SELECT GEOID, NAME, STATE_NAME, ST_GeometryType(geom) AS geom_type
FROM ST_Read('/vsizip/vsicurl/https://www2.census.gov/geo/tiger/GENZ2025/shp/cb_2025_us_county_20m.zip/cb_2025_us_county_20m.shp')
LIMIT 10;

INSTALL httpfs;

LOAD httpfs;
SELECT id, date, element, data_value
FROM read_csv_auto('https://noaa-ghcn-pds.s3.amazonaws.com/csv/by_year/2024.csv')
LIMIT 10;
